/* Company film informs the tools; the batch, method parameters and story are educational. */
(() => {
 'use strict';
 const css=document.createElement('link');css.rel='stylesheet';css.href=new URL('lab-v6.css?v=6.2',document.currentScript.src).href;document.head.append(css);
 const KEY='ochakovo-lab-visual-v6',phases=['Принять пробу','Подготовить','Исследовать','Сверить данные','Передать команде'];
 const D={sample:'L-041',batch:'P-214',tank:'T-07',titre:34,brix:9.2,titreRange:[3.2,3.6],brixRange:[9.8,10.2]};
 const fmt=n=>Number(n).toFixed(1).replace('.',',');
 const paths={check:'m5 12 4 4L19 6',arrow:'M4 12h15m-6-6 6 6-6 6',drop:'M12 2S4 11 4 15a8 8 0 0 0 16 0c0-4-8-13-8-13Z',book:'M5 3h14v18H5zM9 7h6M9 11h6M9 15h4',play:'m9 5 11 7-11 7Z',info:'M12 10v6m0-10v1',mix:'M8 3h8m-6 0v7l-5 9h14l-5-9V3M8 15h8',scan:'M3 8V3h5m8 0h5v5m0 8v5h-5M8 21H3v-5M7 12h10',thermo:'M10 4a2 2 0 0 1 4 0v10a4 4 0 1 1-4 0ZM12 8v9',alert:'m12 3 10 18H2ZM12 9v5m0 3v1'};
 const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.info}"/></svg>`;
 const fresh=()=>({v:6,started:false,phase:0,checks:[],registered:false,prep:0,method:'titre',rig:false,volume:0,mixed:true,titreSaved:false,control:false,clean:false,loaded:false,cover:false,repeatCover:false,brixSaved:false,judgement:'',reported:false,repeatStage:0,done:false});
 const maxPhase=s=>s.reported?4:s.titreSaved&&s.brixSaved?3:s.prep===3?2:s.registered?1:0;
 function restore(){try{const r=JSON.parse(localStorage.getItem(KEY)||'null');if(!r||r.v!==6)return fresh();const s=fresh();for(const k of ['started','registered','rig','mixed','titreSaved','control','clean','loaded','cover','repeatCover','brixSaved','reported','done'])if(typeof r[k]==='boolean')s[k]=r[k];s.checks=[...new Set((Array.isArray(r.checks)?r.checks:[]).filter(x=>['label','source','seal'].includes(x)))];s.prep=Math.max(0,Math.min(3,Math.trunc(Number(r.prep)||0)));s.volume=Math.max(0,Math.min(50,Math.round(Number(r.volume)||0)));s.method=['titre','brix'].includes(r.method)?r.method:'titre';s.judgement=['','hold','release','fix'].includes(r.judgement)?r.judgement:'';s.repeatStage=Math.max(0,Math.min(4,Math.trunc(Number(r.repeatStage)||0)));if(!s.started)return fresh();
  if(!s.registered){s.prep=0;if(!s.checks.includes('label'))s.checks.push('label');}else s.checks=['label','source','seal'];
  if(s.prep<3)Object.assign(s,{rig:false,volume:0,mixed:true,titreSaved:false,control:false,clean:false,loaded:false,cover:false,brixSaved:false});
  if(!s.rig){s.volume=0;s.mixed=true;s.titreSaved=false;}
  if(s.titreSaved&&(s.volume!==D.titre||!s.mixed))s.titreSaved=false;
  if(!s.control)s.clean=s.loaded=s.cover=s.brixSaved=false;
  if(!s.clean)s.loaded=s.cover=s.brixSaved=false;
  if(!s.loaded)s.cover=s.brixSaved=false;
  if(!s.cover)s.brixSaved=false;
  if(!s.titreSaved||!s.brixSaved){s.judgement='';s.reported=false;}
  if(s.judgement!=='hold')s.reported=false;
  if(!s.reported){s.repeatStage=0;s.repeatCover=false;s.done=false;}
  if(s.repeatStage<2)s.repeatCover=false;
  if(s.repeatStage>=3&&!s.repeatCover)s.repeatStage=2;
  if(s.repeatStage<4)s.done=false;
  s.phase=Math.max(0,Math.min(maxPhase(s),Math.trunc(Number(r.phase)||0)));return s;}catch{return fresh();}}
 Object.assign(window.OchakovoShift.roles.lab,{lead:'Прими пробу, проведи титрование и измерение на рефрактометре, передай данные команде.',day:'Химик-лаборант готовит пробы, выполняет исследования по методикам и ведёт записи. В предоставленном ролике показаны работа с бюреткой, лабораторной посудой и настольным рефрактометром.',tools:'Пробы, бюретка, мерная посуда, рефрактометр, контрольные материалы и лабораторный журнал.',learned:'Принял пробу, выполнил учебное титрование и рефрактометрию, сохранил повтор и передал отклонение наставнику.'});
 window.GameMissions.list.find(x=>x.id==='lab').minutes=8;
 window.OchakovoShift.register('lab',a=>{
  let s=restore(),message='',error=false,doc='label',journal=false,video=false,busy=false,measured=false,hint=false,disposed=false,timer=null,storageOK=true;
  const {esc}=a;a.root.classList.add('lab-v6');a.root.querySelector('.shift-heading').hidden=true;a.root.querySelector('.shift-profession').hidden=true;
  const live=a.root.querySelector('.shift-feedback');live.classList.add('lv-announcer');
  const btn=(action,label,cls='',value='',disabled=false,extra='')=>a.button('lv-'+action,label,value,'lv-button '+cls,`${disabled?'disabled':''} ${extra}`);
  const primary=(act,label,disabled=false)=>btn(act,label+icon('arrow'),'lv-primary','',disabled);
  const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(s));storageOK=true;}catch{storageOK=false;}};
  function tell(t,bad=false){message=t;error=bad;live.textContent=t;a.say(t,bad?'think':'welcome');}
  function move(n){s.phase=n;message='';hint=false;save();render();a.content.querySelector('.lv-title')?.focus({preventScroll:true});a.root.scrollIntoView({block:'start',behavior:'instant'});}
  const feedback=()=>message?`<p class="lv-feedback ${error?'is-error':''}">${icon(error?'alert':'check')}${esc(message)}</p>`:'';
  const guide=t=>`<aside class="lv-guide"><img src="assets/ochazhok-illustrated-v2.webp" width="72" height="93" alt="Очажок — твой напарник"><div><strong>Очажок подсказывает</strong><p>${t}</p></div></aside>`;
  const detail=(title,t)=>`<details class="lv-detail"><summary>${title}</summary><p>${t}</p></details>`;
  const bottle=(label='P-214',small=false)=>`<div class="lv-sample ${small?'is-small':''}" aria-hidden="true"><i class="lv-sample-cap"></i><div class="lv-sample-neck"></div><div class="lv-sample-body"><div class="lv-sample-liquid"></div><span><b>${label}</b><small>Основа напитка</small></span></div></div>`;
  function header(){return `<header class="lv-header"><div><h1>Лаборатория</h1><p>Химик-лаборант · исследуй то, что не видно снаружи</p></div><button type="button" class="lv-film-button" data-do="lv-video" aria-expanded="${video}">${icon('play')}Как это в «Очаково»</button></header>${video?`<section class="lv-video"><video controls playsinline preload="metadata" src="assets/lab-work-ochakovo.mp4" aria-label="Ролик Очаково о работе химика-лаборанта"></video><p>Ролик из материалов компании · 32 секунды</p></section>`:''}${s.started?`<nav class="lv-phases" aria-label="Этапы лаборатории">${phases.map((p,i)=>btn('phase',`<span>${i<maxPhase(s)||s.done?icon('check'):i+1}</span><b>${p}</b>`,i===s.phase?'is-current':'',String(i),i>maxPhase(s),`aria-label="${p} · этап ${i+1} из 5" ${i===s.phase?'aria-current="step"':''}`)).join('')}</nav><div class="lv-context"><span>Проба <b>${s.registered?D.sample:'на приёмке'}</b> · ${D.batch} · ${D.tank}</span><span class="lv-status ${s.reported?'is-held':''}">${s.reported?'Удерживается':'На исследовании'}</span>${btn('journal',icon('book')+'Журнал','lv-text','',false,`aria-expanded="${journal}"`)}</div>${journal?journalView():''}`:''}`;}
  function journalView(){return `<section class="lv-journal" aria-label="Лабораторный журнал"><h2>Журнал пробы ${D.sample}</h2><table><thead><tr><th>Исследование</th><th>Результат</th><th>Запись</th></tr></thead><tbody><tr><th>Расход при титровании</th><td>${s.titreSaved?fmt(D.titre/10)+' мл':'—'}</td><td>${s.titreSaved?'Сохранён':'Ожидает исследования'}</td></tr><tr><th>Рефрактометр</th><td>${s.brixSaved?fmt(D.brix)+' °Bx':'—'}</td><td>${s.brixSaved?'Исходный результат':'Ожидает исследования'}</td></tr>${s.repeatStage===4?`<tr><th>Рефрактометр · повтор</th><td>${fmt(D.brix)} °Bx</td><td>Отдельная запись</td></tr>`:''}</tbody></table><p>Учебные значения · ${D.batch} · источник ${D.tank} · ${s.prep>0?'подготовка 20,2 °C':'условия ещё не подготовлены'}</p></section>`;}
  function welcome(){return `<section class="lv-welcome"><div class="lv-welcome-copy"><h2 class="lv-title" tabindex="-1">За вкусом<br>стоят измерения.</h2><p>Снаружи пробы похожи. Узнай, как лаборант замечает то, чего не видно на глаз.</p><div class="lv-welcome-path"><span>${icon('scan')}Прими пробу</span><span>${icon('drop')}Проведи анализы</span><span>${icon('book')}Сохрани вывод</span></div>${primary('start','Начать смену')}<small>Без таймера · можно пробовать снова</small></div><div class="lv-welcome-media"><img class="lv-welcome-lab" src="assets/lab-interior-v1.png" alt="Иллюстрация лаборатории напитков" width="1536" height="1024"><div class="lv-welcome-mascot"><img src="assets/ochazhok-illustrated-v2.webp" alt="Очажок приглашает в лабораторию" width="180" height="230"><p>Одна проба.<br>Два исследования.<br>Твой первый вывод.</p></div></div></section><div class="lv-welcome-foot"><p>В основе сцены — рабочие действия из ролика компании: бюретка, колба и настольный рефрактометр.</p><img src="assets/lab-brand-pattern.jpg" alt="" width="1754" height="1240"></div>`;}
  function receipt(){const docs={label:['Этикетка','Основа напитка','Номер пробы присвоим при регистрации'],source:['Направление','Источник: ёмкость '+D.tank,'Отбор 10:20 · до насыщения газом'],seal:['Осмотр','Ёмкость закрыта','Крышка цела · следов протечки нет']}[doc];return `<div class="lv-work"><section class="lv-table lv-receipt"><div class="lv-scene-label"><span>Приёмный стол</span><span>${s.checks.length} / 3 проверено</span></div><div class="lv-receipt-objects">${bottle()}<article class="lv-document"><span>${docs[0]}</span><strong>${D.batch}</strong><p>${docs[1]}</p><small>${s.registered&&doc==='label'?'Зарегистрирована как '+D.sample:docs[2]}</small><div>${s.checks.includes(doc)?icon('check')+'Сверено':'Открой и сверь'}</div></article></div><div class="lv-object-controls" role="group" aria-label="Осмотр пробы">${[['label','Этикетка'],['source','Направление'],['seal','Крышка']].map(([id,t])=>btn('inspect',(s.checks.includes(id)?icon('check'):icon('scan'))+t,doc===id?'is-current':'',id,false,`aria-pressed="${doc===id}"`)).join('')}</div></section><section class="lv-task"><h2 class="lv-title" tabindex="-1">У каждой пробы<br>есть своя история.</h2><p>Сверь партию, источник и целостность ёмкости. Затем зарегистрируй образец.</p><div class="lv-trace"><span>${D.tank}<small>Источник</small></span>${icon('arrow')}<span>${D.batch}<small>Партия</small></span>${icon('arrow')}<span>${D.sample}<small>Проба</small></span></div>${guide('Число без связи с пробой ничего не говорит о нужной партии. Начнём с этой связи.')}${feedback()}${primary('register',s.registered?'К подготовке':'Зарегистрировать пробу',s.checks.length<3)}${detail('Если этикетку не прочитать?','Не угадывай источник по соседней ёмкости. Сохрани пробу отдельно и уточни сведения у ответственного сотрудника.')}</section></div>`;}
  function preparation(){const steps=[['thermo','Привести к условиям методики','20,2 °C'],['mix','Аккуратно перемешать','Без разбавления и вспенивания'],['drop','Подготовить две порции','Для каждого исследования — своя']];const texts=['Образец поступил с температурой 24,3 °C. В учебной карточке указаны условия 19–21 °C.','Подготовленная порция должна отражать состав образца. Перемешай его аккуратно.','Для двух методов нужны отдельные порции. Использованный раствор не возвращаем в исходную ёмкость.'];return `<div class="lv-work"><section class="lv-table"><div class="lv-scene-label"><span>${D.sample} · подготовка</span><span>${s.prep===0?'24,3':'20,2'} °C</span></div><div class="lv-prep-objects">${bottle(D.sample)}${s.prep===3?`<div class="lv-portions"><div>${bottle('L-041 · A',true)}<b>Титрование</b></div><div>${bottle('L-041 · B',true)}<b>Рефрактометр</b></div></div>`:`<div class="lv-temp"><strong>${s.prep===0?'24,3':'20,2'}<small>°C</small></strong><span>${s.prep===0?'Нужна подготовка':'Условия соблюдены'}</span></div>`}</div><div class="lv-prep-list">${steps.map(([ic,t,sub],i)=>`<div class="${s.prep>i?'is-done':s.prep===i?'is-current':''}">${icon(s.prep>i?'check':ic)}<span><b>${t}</b><small>${sub}</small></span></div>`).join('')}</div></section><section class="lv-task"><h2 class="lv-title" tabindex="-1">${s.prep===3?'Проба готова.<br>Теперь — приборы.':['Создай нужные<br>условия.','Один образец.<br>Однородный состав.','Два исследования.<br>Две чистые порции.'][s.prep]}</h2><p>${s.prep===3?'Начни с любого исследования. Результаты попадут в один журнал.':texts[s.prep]}</p>${guide('Подготовка сохраняет свойства образца. Воду или сироп для «исправления» результата не добавляем.')}${feedback()}${primary(s.prep===3?'to-tests':'prepare',s.prep===3?'К исследованиям':steps[s.prep][1])}</section></div>`;}
  function rig(){const pink=s.volume>=D.titre&&s.mixed;return `<div class="lv-rig ${pink?'is-endpoint':''} ${s.volume>D.titre?'is-over':''}"><img src="assets/lab-titration-v6.png" alt="Бюретка на штативе, коническая колба и белая плитка" width="1280" height="1280"><svg class="lv-fluid" viewBox="0 0 1280 1280" aria-hidden="true"><path class="lv-flask-fill" d="M600 1049 Q677 1068 752 1049 L774 1096 Q760 1130 677 1133 Q593 1129 573 1096Z" fill="${pink?'#e9578a':'#e2c36a'}" opacity="${pink?'.38':'.12'}"/><path class="lv-droplet" d="M676 779s-7 11-7 15a7 7 0 0 0 14 0c0-4-7-15-7-15Z" fill="#d50032" opacity="0"/></svg><div class="lv-volume"><span>Расход титранта</span><strong>${fmt(s.volume/10)}<small>мл</small></strong><span>${!s.rig?'Установка к работе':s.volume>D.titre?'Конечная точка пройдена':pink?'Окраска сохраняется':s.mixed?'Раствор перемешан':'Перемешай колбу'}</span></div><span class="lv-rig-caption">${s.titreSaved?'Результат в журнале':s.volume>D.titre?'Конечная точка пройдена — нужна новая порция':pink?'Слабая окраска после перемешивания':'Очажок за каплей — наблюдай за раствором'}</span></div>`;}
  function refraction(repeat=false){const control=!repeat&&s.control&&!s.clean,loaded=repeat?s.repeatStage>=2:s.loaded||control,closed=repeat?s.repeatCover:s.cover||control,done=repeat?s.repeatStage>=3:measured||s.brixSaved;
   const status=busy?'Показание устанавливается':done?'Стабильно · 20,2 °C':control?'Контроль совпадает · 20,2 °C':closed?'Ячейка закрыта':loaded?'Проба нанесена':(!repeat&&s.clean)|| (repeat&&s.repeatStage===1)?'Ячейка очищена':'Подготовь ячейку';
   return `<div class="lv-refraction ${loaded?'is-loaded':''} ${closed?'is-closed':''} ${busy?'is-measuring':''}"><img src="assets/${closed?'lab-refractometer-closed-v6.png':'lab-refractometer-v6.png'}" alt="Рефрактометр: экран слева, измерительная ячейка справа ${closed?'закрыта':'открыта'}" width="1408" height="1152"><div class="lv-device-display"><strong>${busy?'…':done?fmt(D.brix):control?'10,0':'—'}<small>°Bx</small></strong></div><span class="lv-prism-liquid" aria-hidden="true"></span><div class="lv-pipette" aria-hidden="true"><i></i><b></b><span></span></div></div><div class="lv-instrument-state"><span>${repeat?'Повтор · L-041':control?'Контрольный материал':s.loaded?'Проба L-041':'Измерительная ячейка'}</span><strong>${status}</strong></div>`;
  }
  function tests(){const tit=s.method==='titre';let controls,task;
   if(tit){controls=!s.rig?primary('rig','Подготовить установку'):s.titreSaved?`<p class="lv-operation-done">${icon('check')}Сохранено: ${fmt(D.titre/10)} мл</p>`:`<div class="lv-dose-controls">${btn('dose','+ 1 мл','',10,!s.mixed||s.volume>D.titre)}${btn('dose','По капле · 0,1 мл',s.volume>=30?'is-current':'',1,!s.mixed||s.volume>D.titre)}${btn('mix',icon('mix')+'Перемешать колбу','',0,s.mixed)}</div>`;
    task=`<h2 class="lv-title" tabindex="-1">Точность —<br>в одной капле.</h2><p>Добавляй титрант и перемешивай. Ближе к изменению окраски переходи на капли.</p><ol class="lv-steps"><li class="${s.rig?'is-done':''}">Подготовить установку и записать начало</li><li class="${s.volume>=30?'is-done':''}">Добавлять, наблюдая за раствором</li><li class="${s.volume===D.titre&&s.mixed?'is-done':''}">Поймать конечную точку</li><li class="${s.titreSaved?'is-done':''}">Записать расход</li></ol>${guide(s.volume>D.titre?'Яркая окраска: конечная точка пройдена. Эту порцию повторим, без штрафа.':s.volume>=30?'Добавляй по 0,1 мл и перемешивай после каждой добавки. В конце остаётся слабая розовая окраска.':'Реактивы подготовил наставник. Ты контролируешь добавление, наблюдаешь и ведёшь запись.')}${feedback()}${s.volume>D.titre?primary('retry-titre','Подготовить новую порцию'):s.volume===D.titre&&s.mixed&&!s.titreSaved?primary('save-titre','Записать '+fmt(D.titre/10)+' мл'):s.titreSaved?primary(s.brixSaved?'to-results':'method',s.brixSaved?'Сверить результаты':'К рефрактометру'):''}${detail('Что именно мы измерили?','Здесь записываем расход титранта. По нему и данным утверждённой методики специалист рассчитывает титруемую кислотность. Миллилитры расхода не равны pH. Ход и время реакции упрощены.')}`;
   }else{const action=!s.control?['control','Проверить контрольный материал']:!s.clean?['clean','Очистить измерительную ячейку']:!s.loaded?['load','Нанести порцию L-041']:!s.cover?['cover','Закрыть крышку ячейки']:!measured&&!s.brixSaved?['measure','Начать измерение']:!s.brixSaved?['save-brix','Записать '+fmt(D.brix)+' °Bx']:['to-results','Сверить результаты'];controls=busy?primary('stable','Показать стабильный результат'):primary(action[0],action[1],s.brixSaved&&!s.titreSaved);task=`<h2 class="lv-title" tabindex="-1">Несколько капель.<br>Проверенное число.</h2><p>Прибор измеряет преломление света и показывает результат по шкале °Brix.</p><ol class="lv-steps">${[[s.control,'Проверить контрольный материал'],[s.clean,'Удалить остатки предыдущего раствора'],[s.loaded,'Нанести отдельную порцию'],[s.cover,'Закрыть крышку ячейки'],[s.brixSaved,'Сохранить стабильный результат']].map(([x,t])=>`<li class="${x?'is-done':''}">${t}</li>`).join('')}</ol>${guide(s.control?'Чистая ячейка и подготовленная проба помогают получить достоверный результат.':'Калибровку выполнил наставник. Проверим прибор материалом с известным значением: 10,0 °Bx.')}${feedback()}${s.brixSaved&&!s.titreSaved?btn('method','Перейти к титрованию','lv-text','titre'):''}${detail('°Brix — это сахар или плотность?','На результат по шкале влияют разные растворённые вещества. Это не отдельное измерение чистого сахара и не измерение плотности.')}`;}
   return `<div class="lv-methods" role="group" aria-label="Выбери исследование">${btn('method',icon(s.titreSaved?'check':'drop')+'Титрование',tit?'is-current':'','titre',busy,`aria-pressed="${tit}"`)}${btn('method',icon(s.brixSaved?'check':'drop')+'Рефрактометр',!tit?'is-current':'','brix',busy,`aria-pressed="${!tit}"`)}</div><div class="lv-work"><section class="lv-table lv-analysis"><div class="lv-scene-label"><span>${tit?'Бюретка и колба':'Настольный рефрактометр'}</span><span>${D.sample}</span></div>${tit?rig():refraction()}<div class="lv-tool-actions">${controls}</div></section><section class="lv-task">${task}</section></div>`;}
  function resultRow(title,value,unit,min,max,lo,hi){return `<div class="lv-result-row"><div><h3>${title}</h3><strong>${fmt(value)}<small>${unit}</small></strong></div><div class="lv-range" role="img" aria-label="${title}: ${fmt(value)} ${unit}, учебный диапазон ${fmt(lo)}–${fmt(hi)} ${unit}"><i style="left:${(lo-min)/(max-min)*100}%;width:${(hi-lo)/(max-min)*100}%"></i><b class="${value<lo||value>hi?'is-out':''}" style="left:${(value-min)/(max-min)*100}%"></b></div><p><span>${fmt(min)}</span><span>Карточка: ${fmt(lo)}–${fmt(hi)} ${unit}</span><span>${fmt(max)}</span></p></div>`;}
  function results(){return `<div class="lv-work"><section class="lv-results"><div class="lv-scene-label"><span>Лист результатов</span><span>${D.sample}</span></div>${resultRow('Расход титранта',D.titre/10,'мл',2.8,4,...D.titreRange)}${resultRow('Рефрактометр',D.brix,'°Bx',8.8,10.8,...D.brixRange)}<p class="lv-model-note">Диапазоны только для этой учебной пробы и её порций. Это не нормативы продукции «Очаково».</p></section><section class="lv-task"><h2 class="lv-title" tabindex="-1">Сверь числа.<br>Заметь отклонение.</h2><p>Сопоставь результаты с учебной карточкой. Как передадим пробу дальше?</p><div class="lv-decisions" role="group" aria-label="Решение по результатам">${[['hold','Передать отклонение','°Bx ниже диапазона — нужна проверка'],['release','Передать без замечаний','Не учитывать отклонение °Bx'],['fix','Изменить состав пробы','Добавить сироп до нужного числа']].map(([v,t,d])=>btn('judgement',`<span>${icon(s.judgement===v?'check':'arrow')}</span><div><b>${t}</b><small>${d}</small></div>`,s.judgement===v?'is-selected':'',v,false,`aria-pressed="${s.judgement===v}"`)).join('')}</div>${feedback()}${primary('report','Передать наблюдение',!s.judgement)}${guide('Запиши то, что измерил. Отклонение ещё не доказывает причину и не указывает виновного.')}</section></div>`;}
  function team(){const rs=s.repeatStage;let body;
   if(rs<4){const action=[['repeat-clean','Подготовить прибор и новую порцию'],['repeat-load','Нанести новую порцию L-041'],[s.repeatCover?'repeat-measure':'repeat-cover',s.repeatCover?'Повторить измерение':'Закрыть крышку ячейки'],['repeat-save','Сохранить отдельной записью']][rs];body=`<div class="lv-work"><section class="lv-table lv-analysis"><div class="lv-scene-label"><span>Назначенный повтор</span><span>${D.sample} · новая порция</span></div>${refraction(true)}<div class="lv-tool-actions">${busy?primary('stable','Показать стабильный результат'):primary(action[0],action[1])}</div></section><section class="lv-task"><h2 class="lv-title" tabindex="-1">Повторный анализ.<br>Обе записи важны.</h2><p>Наставник проверил условия и назначил повтор на новой порции исходной пробы.</p><div class="lv-team-chain"><span>${icon('check')}Лаборант сообщил об отклонении</span><span>${icon('check')}Оператор удерживает P-214</span><span>${icon('check')}Качество назначило проверку</span></div>${guide('Повтор не стирает первое число. Запишем его отдельной строкой, чтобы команда видела всю картину.')}${feedback()}${detail('Кто принимает решение о партии?','Лаборант передаёт достоверные данные. Решение по отклонению и дальнейшим действиям принимают уполномоченные специалисты качества вместе с технологом.')}</section></div>`;
   }else body=`<div class="lv-work"><section class="lv-final-report"><div class="lv-scene-label"><span>Заключение для наставника</span><span>${D.sample}</span></div><h2>Отклонение<br>подтверждается.</h2><dl><div><dt>Титрование · расход</dt><dd>${fmt(D.titre/10)} мл</dd></div><div><dt>°Brix · исходный</dt><dd>${fmt(D.brix)} °Bx</dd></div><div><dt>°Brix · повтор</dt><dd>${fmt(D.brix)} °Bx</dd></div><div><dt>Причина</dt><dd>Не установлена</dd></div></dl><p>${icon('alert')}P-214 остаётся на удержании</p></section><section class="lv-task"><h2 class="lv-title" tabindex="-1">${s.done?'Хорошая работа —<br>точный вывод.':'Твой результат<br>нужен команде.'}</h2><p>${s.done?'Ты прошёл путь пробы, работал с двумя методами и сохранил данные, по которым команда может действовать.':'Повтор тоже ниже диапазона. Передай оба результата наставнику. Решение остаётся за ответственными специалистами.'}</p>${guide(s.done?'Не каждая хорошая смена заканчивается разрешением на выпуск. Сегодня ты вовремя заметил отклонение.':'Это учебное сообщение внутри игры. Оно не отправляется на настоящее производство.')}${feedback()}${s.done?a.button('finish','Записать открытие'+icon('arrow'),'','lv-button lv-primary'):primary('handover','Передать запись наставнику')}${s.done?btn('restart','Пройти лабораторию заново','lv-text'):''}</section></div>`;
   return `<div class="lv-hold-banner">${icon('alert')}Партия P-214 удерживается до решения специалиста качества</div>${body}`;}
  function render(){if(disposed)return;const film=video?a.content.querySelector('video'):null,wasPlaying=film&&!film.paused&&!film.ended;a.root.classList.toggle('is-started',s.started);a.settle();const focused=document.activeElement,hadFocus=a.content.contains(focused),active=focused?.closest('[data-do]'),old=active&&hadFocus?{do:active.dataset.do,value:active.dataset.value}:null,summary=focused?.matches('summary')?focused.textContent:null,openDetails=new Set([...a.content.querySelectorAll('details[open]')].map(n=>n.querySelector('summary')?.textContent));a.content.innerHTML=`${header()}<div class="lv-body">${s.started?[receipt,preparation,tests,results,team][s.phase]():welcome()}</div>${s.started?`<footer class="lv-footer">${btn('hint',icon('info')+'Подсказка','lv-text','',false,`aria-expanded="${hint}"`)}<span>${storageOK?'Прогресс сохраняется на устройстве':'Сохранение недоступно — не закрывай вкладку'}</span>${hint?`<p>${['Открой этикетку, направление и крышку. Проверь P-214 и T-07.','Подготовь температуру, перемешай и раздели на две отдельные порции.','После 3,0 мл переходи на капли. Перемешивай после добавления. На рефрактометре подготовь ячейку и сохраняй стабильное показание.','9,2 °Bx ниже 9,8. Передай отклонение, сохраняя исходные данные.','Сделай назначенный повтор, запиши отдельно и передай наставнику.'][s.phase]}</p>`:''}</footer>`:''}<details class="lv-about"><summary>О профессии и учебной сцене</summary><p>Химик-лаборант работает с пробами, методиками, посудой, приборами и записями. В ролике компании показаны титрование и рефрактометрия; сюжет, образец, показатели и диапазоны игры вымышлены. Приборы и реакция изображены упрощённо. Методики, реактивы, расчёт кислотности и допуск к работе определяет наставник. Время реакции в игре сокращено.</p></details>`;for(const d of a.content.querySelectorAll('details'))d.open=openDetails.has(d.querySelector('summary')?.textContent);
   if(film){a.content.querySelector('video')?.replaceWith(film);if(wasPlaying)film.play().catch(()=>{});}
   if(hadFocus){const next=old?[...a.content.querySelectorAll('[data-do]')].find(n=>n.dataset.do===old.do&&n.dataset.value===old.value&&!n.disabled):focused===film?film:summary?[...a.content.querySelectorAll('summary')].find(n=>n.textContent===summary):null;
    (next||a.content.querySelector('.lv-task>.lv-primary:not([disabled])')||a.content.querySelector('.lv-tool-actions button.is-current:not([disabled])')||a.content.querySelector('.lv-tool-actions button:not([disabled])')||a.content.querySelector('.lv-task>.lv-text:not([disabled])')||a.content.querySelector('.lv-title'))?.focus({preventScroll:true});}
  }
  function animate(type){a.animate(g=>{const t=g.timeline();if(type==='dose')t.fromTo(a.content.querySelector('.lv-droplet'),{y:0,opacity:1},{y:190,opacity:0,duration:.55,ease:'power2.in'});else if(type==='mix'||type==='prepare')t.fromTo(a.content.querySelector(type==='mix'?'.lv-flask-fill':'.lv-sample'),{rotation:-2},{rotation:0,duration:.55,ease:'elastic.out(1,.4)',clearProps:'transform'});else if(type==='load'||type==='repeat-load')t.fromTo(a.content.querySelector('.lv-pipette'),{x:18,y:-35,opacity:0},{x:0,y:0,opacity:1,duration:.55,ease:'power2.out',clearProps:'transform,opacity'});else if(type==='inspect')t.fromTo(a.content.querySelector('.lv-document'),{x:12,opacity:.5},{x:0,opacity:1,duration:.25,clearProps:'transform,opacity'});else return null;return t;});}
  function stable(){if(!busy||disposed)return;clearTimeout(timer);timer=null;busy=false;if(s.phase===4)s.repeatStage=3;else measured=true;tell('Показание стабильно: '+fmt(D.brix)+' °Bx. Сохрани его в журнале.');save();render();}
  function measure(){if(busy)return;busy=true;message='';render();if(window.GameMotion?.enabled()===false||window.matchMedia('(prefers-reduced-motion: reduce)').matches){stable();return;}timer=setTimeout(stable,1400);}
  function act(type,value){if(!type.startsWith('lv-'))return;type=type.slice(3);if(type==='video'){video=!video;render();return;}if(type==='journal'){journal=!journal;render();return;}if(type==='hint'){hint=!hint;render();return;}if(type==='phase'){const n=Number(value);if(!busy&&Number.isInteger(n)&&n>=0&&n<=maxPhase(s))move(n);return;}if(type==='stable'){stable();return;}if(type==='restart'){s=fresh();doc='label';measured=false;message='';journal=false;save();render();return;}if(busy)return;message='';error=false;
   if(type==='start'){s.started=true;s.checks=['label'];move(0);return;}
   if(s.phase===0){if(type==='inspect'&&['label','source','seal'].includes(value)){doc=value;if(!s.checks.includes(value))s.checks.push(value);}if(type==='register'&&s.checks.length===3){s.registered=true;move(1);return;}}
   else if(s.phase===1){if(type==='prepare')s.prep=Math.min(3,s.prep+1);if(type==='to-tests'&&s.prep===3){move(2);return;}}
   else if(s.phase===2){if(type==='method')s.method=['titre','brix'].includes(value)?value:'brix';
    if(s.method==='titre'){if(type==='rig'){s.rig=true;tell('Наставник проверил установку. Начальный отсчёт записан: 0,0 мл.');}if(type==='dose'&&s.rig&&s.mixed&&!s.titreSaved){s.volume=Math.min(50,s.volume+Number(value));s.mixed=false;}if(type==='mix'){s.mixed=true;if(s.volume>D.titre)tell('Конечная точка пройдена. Подготовь новую порцию и повтори аккуратнее.',true);else if(s.volume===D.titre)tell('После перемешивания слабая окраска сохраняется. Запиши расход.');else if(s.volume>=30)tell('Окраска ещё не сохраняется. Добавляй по 0,1 мл и перемешивай.');}if(type==='retry-titre'){s.rig=false;s.volume=0;s.mixed=true;tell('Новая порция готова. Предыдущая попытка не используется как результат.');}if(type==='save-titre'&&s.volume===D.titre&&s.mixed){s.titreSaved=true;tell('Расход 3,4 мл сохранён в журнале.');}}
    else{if(type==='control'){s.control=true;tell('Контрольный материал: 10,0 °Bx. Прибор готов; удали контрольный раствор.');}if(type==='clean'&&s.control)s.clean=true;if(type==='load'&&s.clean)s.loaded=true;if(type==='cover'&&s.loaded)s.cover=true;if(type==='measure'&&s.loaded&&s.cover){measure();return;}if(type==='save-brix'&&measured){s.brixSaved=true;tell('Результат 9,2 °Bx сохранён в журнале.');}}
    if(type==='to-results'&&s.titreSaved&&s.brixSaved){move(3);return;}
   }else if(s.phase===3){if(type==='judgement'&&['hold','release','fix'].includes(value))s.judgement=value;if(type==='report'){if(s.judgement==='hold'){s.reported=true;move(4);return;}tell(s.judgement==='fix'?'Не изменяй пробу ради нужного показания. Передай фактическое отклонение.':'Отклонение °Bx нельзя отбросить. Передай его ответственным специалистам.',true);}}
   else if(s.phase===4){if(type==='repeat-clean'&&s.repeatStage===0)s.repeatStage=1;if(type==='repeat-load'&&s.repeatStage===1)s.repeatStage=2;if(type==='repeat-cover'&&s.repeatStage===2)s.repeatCover=true;if(type==='repeat-measure'&&s.repeatStage===2&&s.repeatCover){measure();return;}if(type==='repeat-save'&&s.repeatStage===3){s.repeatStage=4;tell('Повтор 9,2 °Bx сохранён отдельной строкой.');}if(type==='handover'&&s.repeatStage===4){s.done=true;tell('Наставник принял запись. Удержание партии сохраняется.');}}
   save();render();animate(type);
  }
  const onMotion=e=>{if(!e.detail.enabled&&busy)stable();};document.addEventListener('ochakovo:motion',onMotion);
  return {managesFocus:true,start(){render();},act,done:()=>s.done,result:()=>({learned:window.OchakovoShift.roles.lab.learned}),cleanup(){disposed=true;clearTimeout(timer);document.removeEventListener('ochakovo:motion',onMotion);}};
 });
})();
